import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o,c as d,a as n,b as s,d as c,e as i}from"./app-42caee4a.js";const r={},l=n("h1",{id:"博客模板使用说明",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#博客模板使用说明","aria-hidden":"true"},"#"),s(" 博客模板使用说明")],-1),p=n("p",null,[s("这是基于 "),n("strong",null,"VuePress 2 + vuepress-theme-hope"),s(" 的博客模板。本文档详细介绍模板提供的所有功能，以及如何使用和扩展它。")],-1),u=n("code",null,"vuepress-theme-hope-template",-1),v={href:"https://theme-hope.vuejs.press/zh/",target:"_blank",rel:"noopener noreferrer"},h=i(`<h2 id="目录结构" tabindex="-1"><a class="header-anchor" href="#目录结构" aria-hidden="true">#</a> 目录结构</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>src/                    # 博客源码目录（页面都放这里）
├── .vuepress/          # 全局配置
│   ├── config.ts       # 站点配置（标题、描述、base）
│   ├── theme.ts        # 主题配置（作者、导航、功能开关、插件）
│   ├── navbar.ts       # 顶部导航栏
│   ├── sidebar.ts      # 侧边栏
│   └── styles/         # 自定义样式
│       ├── palette.scss    # 主题色
│       ├── config.scss     # 颜色配置
│       └── index.scss      # 自定义全局样式
├── README.md           # 博客主页
└── 文章目录/           # 你写文章的地方（可任意创建）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="快速开始" tabindex="-1"><a class="header-anchor" href="#快速开始" aria-hidden="true">#</a> 快速开始</h2><h3 id="写第一篇文章" tabindex="-1"><a class="header-anchor" href="#写第一篇文章" aria-hidden="true">#</a> 写第一篇文章</h3><p>在 <code>src/</code> 下任意目录新建一个 <code>.md</code> 文件，例如 <code>src/posts/hello.md</code>：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code><span class="token front-matter-block"><span class="token punctuation">---</span>
<span class="token front-matter yaml language-yaml"><span class="token key atrule">title</span><span class="token punctuation">:</span> 你好，世界
<span class="token key atrule">date</span><span class="token punctuation">:</span> <span class="token datetime number">2024-01-01</span>
<span class="token key atrule">author</span><span class="token punctuation">:</span> wangbo
<span class="token key atrule">category</span><span class="token punctuation">:</span> 随笔
<span class="token key atrule">tag</span><span class="token punctuation">:</span>
  <span class="token punctuation">-</span> 入门</span>
<span class="token punctuation">---</span></span>

这里是文章正文，使用 Markdown 语法书写。

博客插件会自动根据 <span class="token code-snippet code keyword">\`category\`</span> 分类、根据 <span class="token code-snippet code keyword">\`tag\`</span> 打标签，并生成时间线。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>保存后，本地运行 <code>pnpm run docs:dev</code> 预览，或推送到 GitHub 后由 Actions 自动构建部署。</p><h3 id="支持的-frontmatter-字段" tabindex="-1"><a class="header-anchor" href="#支持的-frontmatter-字段" aria-hidden="true">#</a> 支持的 Frontmatter 字段</h3><p>博客文章可用的 frontmatter 字段（常用）：</p><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>title</code></td><td>文章标题</td></tr><tr><td><code>date</code></td><td>文章日期（用于排序和时间线）</td></tr><tr><td><code>author</code></td><td>作者（默认使用主题里的全局 author）</td></tr><tr><td><code>category</code></td><td>文章分类（可多个：<code>category: [A, B]</code>）</td></tr><tr><td><code>tag</code> / <code>tags</code></td><td>文章标签</td></tr><tr><td><code>sticky</code></td><td>置顶（数字越大越靠前）</td></tr><tr><td><code>draft</code></td><td>设为 <code>true</code> 则草稿不发布</td></tr><tr><td><code>cover</code></td><td>文章封面图</td></tr><tr><td><code>icon</code></td><td>文章图标</td></tr><tr><td><code>description</code></td><td>摘要（默认自动截取正文前若干字）</td></tr><tr><td><code>image</code></td><td>封面图（同 cover）</td></tr></tbody></table><h2 id="博客功能" tabindex="-1"><a class="header-anchor" href="#博客功能" aria-hidden="true">#</a> 博客功能</h2><p>本模板通过 <code>blog: true</code> 启用了博客插件，自动生成以下页面：</p><ul><li><strong>文章列表</strong> — <code>/article/</code>，按时间倒序列出全部文章</li><li><strong>分类</strong> — <code>/category/</code>，按 <code>category</code> 分组</li><li><strong>标签</strong> — <code>/tag/</code>，按 <code>tag</code> 分组</li><li><strong>时间线</strong> — <code>/timeline/</code>，按年份归档</li><li><strong>博主信息</strong> — 显示博客描述与社交链接（<code>theme.ts</code> 中的 <code>blog</code> 配置）</li></ul><h3 id="博主信息配置" tabindex="-1"><a class="header-anchor" href="#博主信息配置" aria-hidden="true">#</a> 博主信息配置</h3><p>在 <code>src/.vuepress/theme.ts</code> 中：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code>blog<span class="token operator">:</span> <span class="token punctuation">{</span>
  description<span class="token operator">:</span> <span class="token string">&quot;你的博客介绍&quot;</span><span class="token punctuation">,</span>        <span class="token comment">// 博主自我介绍</span>
  medias<span class="token operator">:</span> <span class="token punctuation">{</span>
    GitHub<span class="token operator">:</span> <span class="token string">&quot;https://github.com/你的账号&quot;</span><span class="token punctuation">,</span> <span class="token comment">// 社交图标，可加多个</span>
    <span class="token comment">// BiliBili: &quot;https://...&quot;,</span>
    <span class="token comment">// Zhihu: &quot;https://...&quot;,</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="顶部导航栏-navbar" tabindex="-1"><a class="header-anchor" href="#顶部导航栏-navbar" aria-hidden="true">#</a> 顶部导航栏（navbar）</h2><p>编辑 <code>src/.vuepress/navbar.ts</code>：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token function">navbar</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
  <span class="token string">&quot;/&quot;</span><span class="token punctuation">,</span>                                        <span class="token comment">// 首页</span>
  <span class="token string">&quot;/posts/&quot;</span><span class="token punctuation">,</span>                                  <span class="token comment">// 文章目录</span>
  <span class="token punctuation">{</span>
    text<span class="token operator">:</span> <span class="token string">&quot;分类&quot;</span><span class="token punctuation">,</span>                             <span class="token comment">// 下拉菜单</span>
    icon<span class="token operator">:</span> <span class="token string">&quot;folder&quot;</span><span class="token punctuation">,</span>
    children<span class="token operator">:</span> <span class="token punctuation">[</span>
      <span class="token punctuation">{</span> text<span class="token operator">:</span> <span class="token string">&quot;前端&quot;</span><span class="token punctuation">,</span> icon<span class="token operator">:</span> <span class="token string">&quot;code&quot;</span><span class="token punctuation">,</span> link<span class="token operator">:</span> <span class="token string">&quot;/category/前端/&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
      <span class="token punctuation">{</span> text<span class="token operator">:</span> <span class="token string">&quot;随笔&quot;</span><span class="token punctuation">,</span> icon<span class="token operator">:</span> <span class="token string">&quot;pen&quot;</span><span class="token punctuation">,</span> link<span class="token operator">:</span> <span class="token string">&quot;/category/随笔/&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="侧边栏-sidebar" tabindex="-1"><a class="header-anchor" href="#侧边栏-sidebar" aria-hidden="true">#</a> 侧边栏（sidebar）</h2><p>编辑 <code>src/.vuepress/sidebar.ts</code>：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token function">sidebar</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
  <span class="token string-property property">&quot;/&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>
      text<span class="token operator">:</span> <span class="token string">&quot;文章&quot;</span><span class="token punctuation">,</span>
      icon<span class="token operator">:</span> <span class="token string">&quot;book&quot;</span><span class="token punctuation">,</span>
      prefix<span class="token operator">:</span> <span class="token string">&quot;posts/&quot;</span><span class="token punctuation">,</span>        <span class="token comment">// 前缀，自动拼到子项前面</span>
      children<span class="token operator">:</span> <span class="token string">&quot;structure&quot;</span><span class="token punctuation">,</span>   <span class="token comment">// 自动扫描该目录结构</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>children: &quot;structure&quot;</code> 会自动扫描 <code>prefix</code> 目录下的所有 Markdown 文件并按目录结构生成侧边栏，非常适合存放大量文章。</p><h2 id="强大的-markdown-增强功能" tabindex="-1"><a class="header-anchor" href="#强大的-markdown-增强功能" aria-hidden="true">#</a> 强大的 Markdown 增强功能</h2><p>模板启用了 <code>mdEnhance</code> 插件，几乎全套功能开放。以下都可直接在文章中使用：</p><h3 id="对齐-标记-上下标" tabindex="-1"><a class="header-anchor" href="#对齐-标记-上下标" aria-hidden="true">#</a> 对齐 / 标记 / 上下标</h3><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>::: left
左对齐内容
:::

::: right
右对齐内容
:::

==高亮文本==

上标 2^10^  下标 H<span class="token strike"><span class="token punctuation">~</span><span class="token content">2</span><span class="token punctuation">~</span></span>O
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="图表-chart-echarts-mermaid-flowchart" tabindex="-1"><a class="header-anchor" href="#图表-chart-echarts-mermaid-flowchart" aria-hidden="true">#</a> 图表（chart / echarts / mermaid / flowchart）</h3><p>在代码块中指定语言即可渲染图表，例如用 <code>chart</code>、<code>echarts</code>、<code>mermaid</code> 或 <code>flowchart</code> 作为代码块语言标记。</p><h3 id="选项卡-代码组-code-tabs" tabindex="-1"><a class="header-anchor" href="#选项卡-代码组-code-tabs" aria-hidden="true">#</a> 选项卡 / 代码组（code-tabs）</h3><p>用 <code>::: code-tabs</code> 和 <code>@tab 标签名</code> 组织多语言代码：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>::: code-tabs
@tab JavaScript
console.log(&quot;js&quot;);
@tab Python
print(&quot;python&quot;)
:::
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="图片尺寸-懒加载" tabindex="-1"><a class="header-anchor" href="#图片尺寸-懒加载" aria-hidden="true">#</a> 图片尺寸 / 懒加载</h3><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code><span class="token url"><span class="token operator">!</span>[<span class="token content">图片</span>](<span class="token url">/logo.svg</span>)</span>{width=200px height=100px}   <span class="token comment">&lt;!-- 指定尺寸 --&gt;</span>

![](/logo.svg)                                 <span class="token comment">&lt;!-- 默认懒加载 --&gt;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="数学公式-katex" tabindex="-1"><a class="header-anchor" href="#数学公式-katex" aria-hidden="true">#</a> 数学公式（KaTeX）</h3><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>行内公式 $E = mc^2$

$$
\\frac{1}{2} + \\frac{1}{3}
$$
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="幻灯片-presentation" tabindex="-1"><a class="header-anchor" href="#幻灯片-presentation" aria-hidden="true">#</a> 幻灯片（Presentation）</h3><p>在 frontmatter 加 <code>layout: Slide</code>，正文用幻灯片语法（基于 reveal.js），支持高亮、数学、搜索、笔记、缩放（<code>presentation: [&quot;highlight&quot;, &quot;math&quot;, &quot;search&quot;, &quot;notes&quot;, &quot;zoom&quot;]</code>）。</p><h3 id="其它" tabindex="-1"><a class="header-anchor" href="#其它" aria-hidden="true">#</a> 其它</h3><ul><li><strong>Tabs 选项卡</strong>：<code>:tabs</code> / <code>::: tabs</code></li><li><strong>图注 figure</strong>：<code>![描述](/img.png) **图注**</code></li><li><strong>推荐标记</strong>：<code>*Recommended*</code> 会自动渲染成「推荐」徽章（stylize 规则）</li><li><strong>Playground / Vue Playground</strong>：在线运行 Vue 或 TS 代码</li></ul><h2 id="评论系统" tabindex="-1"><a class="header-anchor" href="#评论系统" aria-hidden="true">#</a> 评论系统</h2><p>模板默认配置了 <strong>Waline</strong>（当前是官方演示服务）：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code>comment<span class="token operator">:</span> <span class="token punctuation">{</span>
  provider<span class="token operator">:</span> <span class="token string">&quot;Waline&quot;</span><span class="token punctuation">,</span>
  serverURL<span class="token operator">:</span> <span class="token string">&quot;https://waline-comment.vuejs.press&quot;</span><span class="token punctuation">,</span> <span class="token comment">// 换你自己部署的服务地址</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如需启用自己的评论，把 <code>serverURL</code> 替换为自建 Waline 服务即可。</p><h2 id="自定义样式" tabindex="-1"><a class="header-anchor" href="#自定义样式" aria-hidden="true">#</a> 自定义样式</h2><ul><li><strong>主题色</strong>：改 <code>src/.vuepress/styles/palette.scss</code> 里的 <code>$theme-color</code>。</li><li><strong>可选颜色</strong>：改 <code>src/.vuepress/styles/config.scss</code> 里的 <code>$colors</code>（影响代码高亮等）。</li><li><strong>全局样式</strong>：在 <code>src/.vuepress/styles/index.scss</code> 里写自定义 CSS/SCSS。</li></ul><h2 id="pwa-渐进式-web-应用" tabindex="-1"><a class="header-anchor" href="#pwa-渐进式-web-应用" aria-hidden="true">#</a> PWA（渐进式 Web 应用）</h2><p><code>theme.ts</code> 中有一段被注释的 <code>pwa</code> 配置。如需支持离线访问、安装到桌面，取消注释并填好 <code>favicon</code>、<code>manifest</code> 图标路径（<code>src/.vuepress/public/assets/icon/</code> 下已有示例图标），然后启用 <code>pwa</code> 插件即可。</p><h2 id="部署到-github-pages" tabindex="-1"><a class="header-anchor" href="#部署到-github-pages" aria-hidden="true">#</a> 部署到 GitHub Pages</h2><p>模板自带 <code>.github/workflows/deploy-docs.yml</code>：推送代码到 <code>main</code> 分支后，GitHub Actions 会自动构建 <code>vuepress build</code> 并部署到 <code>gh-pages</code> 分支。</p><p><strong>前置条件</strong>：在仓库 <strong>Settings → Pages → Build and deployment</strong> 将 Source 设为 <strong>Deploy from a branch</strong>，分支选择 <strong><code>gh-pages</code></strong>，目录 <code>/</code>（root）。</p><h2 id="常用命令" tabindex="-1"><a class="header-anchor" href="#常用命令" aria-hidden="true">#</a> 常用命令</h2><table><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>pnpm install</code></td><td>安装依赖</td></tr><tr><td><code>pnpm run docs:dev</code></td><td>本地开发预览（带热更新）</td></tr><tr><td><code>pnpm run docs:build</code></td><td>生产构建（输出到 <code>src/.vuepress/dist</code>）</td></tr><tr><td><code>pnpm run docs:clean-dev</code></td><td>清缓存后开发预览</td></tr><tr><td><code>pnpm run docs:update-package</code></td><td>升级主题相关依赖</td></tr></tbody></table><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题" aria-hidden="true">#</a> 常见问题</h2><ul><li><strong>新增文章不显示？</strong> 确认 frontmatter 有 <code>title</code>，且不是 <code>draft: true</code>。</li><li><strong>改完配置不生效？</strong> <code>theme.ts</code> 是 TS 文件，改完重启 <code>docs:dev</code>（或重跑 <code>docs:build</code>）。</li><li><strong>图片路径？</strong> 放到 <code>src/.vuepress/public/</code> 下，引用时用 <code>/文件名</code>（根路径）。</li></ul>`,55);function m(b,k){const e=t("ExternalLinkIcon");return o(),d("div",null,[l,p,n("blockquote",null,[n("p",null,[s("模板源："),u,s("，主题文档见 "),n("a",v,[s("vuepress-theme-hope"),c(e)]),s("。")])]),h])}const q=a(r,[["render",m],["__file","index.html.vue"]]);export{q as default};
